// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }
    function testRegression_property() public {
        vm.deal(address(this), 1 ether);
        (bool okFallback,) = address(c).call{value: 1 wei}("");
        assertTrue(okFallback);
        address target = address(0x1234);
        vm.deal(target, 0);
        vm.prank(address(this));
        bool okSend;
        try c.sendMoney(target, address(c).balance) {
            okSend = true;
        } catch {
            okSend = false;
        }
        assertTrue(okSend);
    }
}
